package com.pcguard.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="computers") public class Computer { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="agent_id",unique=true,nullable=false) public String agentId; public String hostname; @Column(name="operating_system") public String operatingSystem; @Column(name="os_version") public String osVersion; public String architecture; @Enumerated(EnumType.STRING) public Status status=Status.UNKNOWN; @Column(name="last_seen") public Instant lastSeen; @Column(name="registered_at") public Instant registeredAt; @Column(name="ip_address") public String ipAddress; @Column(name="mac_address") public String macAddress; @Column(name="agent_version") public String agentVersion; public enum Status { ONLINE,OFFLINE,WARNING,CRITICAL,UNKNOWN } }
